                tempSvg = new SVGElement(document);
                tempSvg.attributes.set('viewBox', new Property(document, 'viewBox', element.getAttribute('viewBox').getString()));
                tempSvg.attributes.set('preserveAspectRatio', new Property(document, 'preserveAspectRatio', element.getAttribute('preserveAspectRatio').getString()));
                tempSvg.attributes.set('overflow', new Property(document, 'overflow', element.getAttribute('overflow').getString()));
                tempSvg.children = element.children;
                // element is still the parent of the children
                element.styles.set('opacity', new Property(document, 'opacity', this.calculateOpacity()));
