const equivalenceMap = {
  'EPSG:4490': 'EPSG:4326',
  'EPSG:4326': 'EPSG:4490',
  'EPSG:3857': 'EPSG:900913',
  'EPSG:900913': 'EPSG:3857'
};
class CRSManager {
  constructor(proj4) {
    this.proj4 = proj4;
    this.builtInEPSG = ['EPSG:3857', 'EPSG:4326'];
  }

  isSameProjection(map, epsgCode) {
    const mapEpsgCode = map.getCRS().epsgCode;
    return mapEpsgCode === epsgCode || 
          (equivalenceMap[mapEpsgCode] === epsgCode && equivalenceMap[epsgCode] === mapEpsgCode);
  }

  getProj4() {
    return this.proj4 || (external_mapboxgl_default()).proj4;
  }

  getCRS(epsgCode) {
    return external_mapboxgl_default().CRS.get(epsgCode);
  }

  registerCRS({ name, wkt, extent, unit }, autoRegister = true) {
    let crs = external_mapboxgl_default().CRS.get(name);
    if (!crs) {
      crs = new (external_mapboxgl_default()).CRS(name, wkt, extent, unit || extent[2] > 180 ? 'meter' : 'degree');
      autoRegister && external_mapboxgl_default().CRS.set(crs);
    }
    if (this.proj4 && !this.builtInEPSG.includes(name)) {
      this.proj4.defs(name, crs.getWKT());
    }
    return crs;
  }
}

